/// <reference types="cypress" />
/// <reference types="@testing-library/cypress" />
/**
 * Lane-local helpers for the Dialogue Cypress journey specs.
 *
 * Ported from the retired Playwright helper (frontends/e2e/tests/helpers/dialogue.ts)
 * and re-shaped for Cypress: BFF calls go through cy.request against the shell-bff
 * proxy (baseUrl :5173 → /api/v1/dialogue → dialogue-bff). After cy.login() the
 * session cookie rides along automatically, so RLS/JWT behave exactly as in prod.
 *
 * i18n rule: prefer semantic queries (findByRole/Text/Label) on OUR pages. The
 * conversation-row / message-bubble / channel-type-tile testids used here are
 * STRUCTURAL anchors (id-suffixed list rows / bubbles with no stable accessible
 * name), never a shortcut past a translated label.
 */

/** shell-bff proxies /api/v1/dialogue/* → dialogue-bff (authenticated plane). */
export const DIALOGUE_API = "/api/v1/dialogue";

/**
 * dialogue-bff's DIRECT host origin. The channel-webhook surface is the only
 * unauthenticated dialogue plane; external providers call it here directly, NOT
 * through shell-bff's authenticated proxy (which would 401 without a session).
 * Override with CYPRESS_DIALOGUE_BFF_URL for a non-default stack.
 */
export function dialogueBffUrl(): string {
  return (Cypress.env("DIALOGUE_BFF_URL") as string) ?? "http://localhost:8086";
}

/**
 * Webhook HMAC secret used when creating dev-mode channels below. Telegram
 * dev-mode (DIALOGUE_TELEGRAM_DEV_MODE=true) is on in the compose stack; the
 * webhook receiver validates X-Hub-Signature-256 = HMAC-SHA256(body, secret).
 * Override via CYPRESS_DIALOGUE_WEBHOOK_SECRET if a stack seeds a different one.
 */
export function webhookSecret(): string {
  return (Cypress.env("DIALOGUE_WEBHOOK_SECRET") as string) ?? "e2e-test-secret";
}

interface Envelope<T> {
  data: T | null;
  error?: { code: string; message: string };
}

export interface ChannelFixture {
  id: string;
  name: string;
  type: string;
}

export interface ContactFixture {
  id: string;
  display_name: string;
  email?: string;
}

export interface ConversationFixture {
  id: string;
  channel_id: string;
  external_thread_id?: string;
}

export interface TemplateFixture {
  id: string;
  name: string;
  body?: string;
  content?: string;
}

export interface TagFixture {
  id: string;
  name: string;
  color?: string;
}

type Method = "GET" | "POST" | "PATCH" | "PUT" | "DELETE";

/**
 * Authenticated BFF call via cy.request. Unwraps the { data, error } envelope
 * and yields `data`. Mutations carry an Idempotency-Key — dialogue-bff honors
 * it for replay-safe retries (Task 6.4) but the header is OPTIONAL repo-wide
 * (Task 6 decision: the platform idempotency middleware no-ops when it is
 * absent), so dialogue-bff never rejects a write for omitting it. Fails the
 * test on >= 400 unless `failOnStatusCode:false`.
 */
export function dlgRequest<T>(
  method: Method,
  path: string,
  body?: unknown,
  opts: { failOnStatusCode?: boolean } = {},
): Cypress.Chainable<Cypress.Response<Envelope<T>>> {
  const headers: Record<string, string> = { Accept: "application/json" };
  if (body !== undefined) headers["Content-Type"] = "application/json";
  if (method !== "GET") headers["Idempotency-Key"] = crypto.randomUUID();
  const options: Partial<Cypress.RequestOptions> = {
    method,
    url: `${DIALOGUE_API}${path}`,
    headers,
    failOnStatusCode: opts.failOnStatusCode ?? true,
  };
  if (body !== undefined) options.body = body as Cypress.RequestBody;
  return cy.request<Envelope<T>>(options);
}

/** dlgRequest that yields the unwrapped envelope `data`. */
export function dlgData<T>(method: Method, path: string, body?: unknown): Cypress.Chainable<T> {
  return dlgRequest<T>(method, path, body).then((res) =>
    cy.wrap((res.body?.data ?? null) as T, { log: false }),
  );
}

// ---------------------------------------------------------------------------
// Fixture creators (BFF-side setup, kept out of the UI so specs stay focused)
// ---------------------------------------------------------------------------

export function createTelegramChannel(name: string): Cypress.Chainable<ChannelFixture> {
  // dialogue-bff only accepts config keys { bot_token, allowed_chat_id } for
  // TELEGRAM_BOT — the webhook secret is server-managed (Vault), not caller-set.
  return dlgData<ChannelFixture>("POST", "/channels", {
    type: "TELEGRAM_BOT",
    name,
    config: { bot_token: "0000000000:AAEtest_fake_bot_token_for_e2e_only" },
  });
}

export function createEmailChannel(name: string): Cypress.Chainable<ChannelFixture> {
  return dlgData<ChannelFixture>("POST", "/channels", {
    type: "EMAIL",
    name,
    config: {
      smtp_host: "mailpit",
      smtp_port: 1025,
      smtp_user: "test@example.com",
      smtp_password: "mailpit-test",
      smtp_from: "test@example.com",
      imap_host: "mailpit",
      imap_port: 1143,
      imap_user: "test@example.com",
      imap_password: "mailpit-test",
      imap_mailbox: "INBOX",
      imap_tls: false,
    },
  });
}

/**
 * Move a channel to its authenticated state (colon-action). Dev-mode adapters
 * (telegram) return 200 here; note that a fake-token telegram bot still cannot
 * register a real webhook, so inbound delivery stays unavailable (see report).
 */
export function authenticateChannel(channelId: string): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "POST",
    url: `${DIALOGUE_API}/channels/${channelId}:authenticate`,
    headers: { "Idempotency-Key": crypto.randomUUID() },
    failOnStatusCode: false,
  });
}

/** Contacts require a channel_id + identifier (BFF-validated). */
export function createContact(
  channelId: string,
  displayName: string,
  identifier: string,
): Cypress.Chainable<ContactFixture> {
  return dlgData<ContactFixture>("POST", "/contacts", {
    channel_id: channelId,
    display_name: displayName,
    identifier,
  });
}

/**
 * Create a conversation and yield its id. The POST response shape is
 * inconsistent across builds, so we resolve the id by listing conversations and
 * matching on channel_id + contact_id (newest wins).
 */
export function createConversation(
  channelId: string,
  contactId: string,
): Cypress.Chainable<string> {
  return dlgRequest("POST", "/conversations", { channel_id: channelId, contact_id: contactId }).then(
    (res) => {
      const direct = (res.body?.data as { id?: string } | null)?.id;
      if (direct) return cy.wrap(direct, { log: false });
      return dlgData<{ conversations?: Array<{ id: string; channel_id: string; contact_id: string }> }>(
        "GET",
        "/conversations",
      ).then((data) => {
        const list = data?.conversations ?? [];
        const match = list.filter((c) => c.channel_id === channelId && c.contact_id === contactId).pop();
        if (!match) throw new Error("createConversation: could not resolve conversation id from list");
        return match.id;
      });
    },
  );
}

export function createTemplate(name: string, content: string): Cypress.Chainable<TemplateFixture> {
  return dlgData<TemplateFixture>("POST", "/templates", { name, content });
}

export interface ThreadSeed {
  channelId: string;
  contactId: string;
  convId: string;
}

/**
 * Create a channel + contact + conversation and yield their ids — the minimal
 * fixture needed to render a thread two-pane at /dialogue/c/<convId>. The
 * channel cannot reach ACTIVE on the fakes-free stack, so this seeds the thread
 * shell (composer, draft, template picker) but not deliverable messages.
 */
export function seedThread(): Cypress.Chainable<ThreadSeed> {
  return createTelegramChannel(uniq("cy-ch")).then((channel) => {
    authenticateChannel(channel.id);
    return createContact(channel.id, uniq("cy-ct"), `${Date.now() % 1_000_000}`).then((contact) =>
      createConversation(channel.id, contact.id).then((convId) => ({
        channelId: channel.id,
        contactId: contact.id,
        convId,
      })),
    );
  });
}

// ---------------------------------------------------------------------------
// Structural selector helpers (id-suffixed lists / bubbles)
// ---------------------------------------------------------------------------

/** The conversation inbox rows (clickable). Id-suffixed structural anchors. */
export function conversationItems(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid^="conversation-item-"]');
}

/** All rendered message bubbles in the open thread. */
export function messageBubbles(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid^="message-bubble-"]');
}

/** The composer container (structural anchor to scope send/textarea within). */
export function composer(): Cypress.Chainable<JQuery<HTMLElement>> {
  return cy.get('[data-testid="composer"]');
}

/** The composer textarea, located by its accessible name ("Write a message…"). */
export function composerTextarea(): Cypress.Chainable<JQuery<HTMLElement>> {
  return composer().findByRole("textbox", { name: /write a message/i });
}

/** The composer Send button (aria-label "Send"), scoped to the composer. */
export function composerSend(): Cypress.Chainable<JQuery<HTMLElement>> {
  return composer().findByRole("button", { name: /^send$/i });
}

// ---------------------------------------------------------------------------
// Channel-create UI entry
// ---------------------------------------------------------------------------

/**
 * Open the tile-based channel-create wizard for a given channel type.
 * ChannelCreateRoute renders a grid of tiles until ?type= is set; the tile
 * testid is the only stable structural anchor for it.
 */
export function openChannelCreate(type: string): void {
  cy.visit("/dialogue/channels/new");
  cy.get(`[data-testid="channel-type-tile-${type}"]`, { timeout: 20_000 }).click();
}

// ---------------------------------------------------------------------------
// Webhook signing (unauthenticated ingest surface)
// ---------------------------------------------------------------------------

/**
 * HMAC-SHA256 hex digest of `body` keyed by `secret`, via the Web Crypto API
 * (localhost is a secure context, so crypto.subtle is available). Returns a
 * Promise; call sites wrap it with cy.wrap(...) to fold it into the command
 * queue.
 */
export async function hmacSha256Hex(body: string, secret: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await globalThis.crypto.subtle.importKey(
    "raw",
    enc.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await globalThis.crypto.subtle.sign("HMAC", key, enc.encode(body));
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** Build a minimal Telegram text-message Update payload. */
export function telegramTextUpdate(opts: {
  messageId: number;
  chatId: number;
  fromId: number;
  text: string;
}): Record<string, unknown> {
  return {
    update_id: opts.messageId * 10 + 1,
    message: {
      message_id: opts.messageId,
      from: {
        id: opts.fromId,
        is_bot: false,
        first_name: "E2E",
        last_name: "TestUser",
        username: "e2e_testuser",
      },
      chat: {
        id: opts.chatId,
        type: "private",
        first_name: "E2E",
        last_name: "TestUser",
        username: "e2e_testuser",
      },
      date: Math.floor(Date.now() / 1000),
      text: opts.text,
    },
  };
}

/** Build a Telegram edited_message Update (same message_id, new text). */
export function telegramEditUpdate(opts: {
  messageId: number;
  chatId: number;
  fromId: number;
  text: string;
}): Record<string, unknown> {
  return {
    update_id: opts.messageId * 10 + 2,
    edited_message: {
      message_id: opts.messageId,
      from: {
        id: opts.fromId,
        is_bot: false,
        first_name: "E2E",
        last_name: "TestUser",
        username: "e2e_testuser",
      },
      chat: {
        id: opts.chatId,
        type: "private",
        first_name: "E2E",
        last_name: "TestUser",
        username: "e2e_testuser",
      },
      date: Math.floor(Date.now() / 1000),
      edit_date: Math.floor(Date.now() / 1000),
      text: opts.text,
    },
  };
}

/**
 * POST a signed Telegram Update to the UNAUTHENTICATED webhook surface and yield
 * the raw response (caller asserts status). The endpoint publishes to NATS and
 * never touches Postgres, so it accepts without a session cookie.
 */
export function postTelegramWebhook(
  channelId: string,
  update: Record<string, unknown>,
  secret = webhookSecret(),
): Cypress.Chainable<Cypress.Response<unknown>> {
  const bodyStr = JSON.stringify(update);
  return cy.wrap(hmacSha256Hex(bodyStr, secret), { log: false }).then((sig) =>
    cy.request({
      method: "POST",
      // Hit dialogue-bff DIRECTLY — the webhook is the unauthenticated plane.
      url: `${dialogueBffUrl()}${DIALOGUE_API}/webhooks/telegram/${channelId}`,
      headers: {
        "Content-Type": "application/json",
        "X-Hub-Signature-256": `sha256=${sig}`,
        "X-Telegram-Bot-Api-Secret-Token": secret,
      },
      body: bodyStr,
      failOnStatusCode: false,
    }),
  );
}

/** A short unique suffix for run-isolated fixture names on the shared stack. */
export function uniq(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1e4)}`;
}


