/**
 * Dialogue — AI draft assist (Draft with AI).
 *
 * Subsumes the retired dialogue-ai-draft.spec.ts. Per the lane brief we assert
 * the draft REQUEST/UI acceptance — the popover opens, a prompt is entered, and
 * submitting issues the :draftWithAI SSE request — NOT the generated content
 * (which depends on LiteLLM/inference availability and is non-deterministic).
 *
 * Persona: P4 (org member).
 */
import { seedThread, DIALOGUE_API } from "./_helpers";

describe("dialogue: AI draft", () => {
  beforeEach(() => {
    cy.login("P4");
  });

  it("opens the Draft-with-AI popover and issues a draft request", () => {
    // Observe the SSE draft request to prove acceptance without asserting content.
    cy.intercept("POST", `${DIALOGUE_API}/conversations/*:draftWithAI`).as("draft");

    seedThread().then(({ convId }) => {
      cy.visit(`/dialogue/c/${convId}`);

      cy.findByRole("button", { name: /draft ai/i }).click();

      cy.findByRole("dialog", { name: /draft with ai/i })
        .should("be.visible")
        .within(() => {
          cy.findByLabelText(/prompt/i).type("Thank the customer for reaching out");
          cy.findByRole("button", { name: /generate draft/i }).click();
        });

      // The request was issued and accepted by the BFF (2xx SSE open). Content
      // streaming is intentionally not asserted.
      cy.wait("@draft", { timeout: 20_000 }).its("response.statusCode").should("be.within", 200, 299);
    });
  });
});


