/**
 * Dialogue — Broadcasts.
 *
 * Subsumes the reachable part of the retired dialogue-broadcasts.spec.ts. The
 * broadcast WRITE actions (Save draft / Schedule / Send now) are admin-gated in
 * BroadcastNewRoute via the SAME defect that blocks Tags: dialogue-mfe
 * useSession drops the session's `org_role`, and the route derives isAdmin from
 * realm `roles` (["offline_access", …]) — never "admin"/"owner" — so those
 * actions never render for any persona (org owner included). This is reported to
 * the lead. Until it's fixed, the sending journey (create draft → send → poll
 * terminal state) is a known gap. This spec asserts the reachable surface: the
 * broadcasts list and the new-broadcast form fields.
 *
 * Persona: P2 (org owner) — highest-privilege reachable persona.
 */
import { uniq } from "./_helpers";

describe("dialogue: broadcasts", () => {
  beforeEach(() => {
    cy.login("P2");
  });

  it("renders the broadcasts list", () => {
    cy.visit("/dialogue/broadcasts");
    cy.findByRole("heading", { name: /^broadcasts$/i }).should("be.visible");
  });

  it("renders the new-broadcast form", () => {
    cy.visit("/dialogue/broadcasts/new");
    cy.get('[data-testid="broadcast-name-input"]', { timeout: 20_000 }).should("be.visible");
    cy.get('[data-testid="broadcast-name-input"]').type(uniq("cy-bc"));
    cy.get('[data-testid="broadcast-body-textarea"]').should("be.visible");
  });
});


--- frontends/cypress/cypress/e2e/dialogue/channels-crud.cy.ts (108 lines) ---
/**
 * Dialogue — channel create wizard (per-channel-type).
 *
 * Subsumes the create side of the retired Playwright specs:
 *   dialogue-telegram-webhook (channel create), dialogue-telegram-client-link,
 *   dialogue-signal-link, dialogue-instagram, dialogue-x-channel.
 *
 * The channel-create surface is a tile grid (ChannelTypeSelector) that routes to
 * a per-type form via ?type=. TELEGRAM_BOT runs in dev-mode (no real bot token,
 * no external fake) so we drive its full happy-path create + confirmation. The
 * other adapters (Telegram Client, Signal, Instagram, X) need external transport
 * fakes to reach ACTIVE — those fakes are NOT in the base stack — so for them we
 * assert the create SURFACE renders (tile → form fields → submit), which is the
 * create side those PW specs owned. Reaching ACTIVE is covered when the adapter
 * fakes are brought up (make dialogue-*-up).
 *
 * Persona: P2 (org owner) — channel setup is an org-admin flavored task.
 */
import { openChannelCreate, uniq } from "./_helpers";

describe("dialogue: channel create wizard", () => {
  beforeEach(() => {
    cy.login("P2");
  });

  it("offers a tile for every supported channel type", () => {
    cy.visit("/dialogue/channels/new");
    for (const type of [
      "EMAIL",
      "TELEGRAM_BOT",
      "TELEGRAM_CLIENT",
      "SIGNAL",
      "INSTAGRAM_DIRECT",
      "SOCIAL_X",
    ]) {
      cy.get(`[data-testid="channel-type-tile-${type}"]`, { timeout: 20_000 }).should(
        "be.visible",
      );
    }
  });

  it("creates a Telegram Bot channel end-to-end (dev-mode) and lists it", () => {
    const name = uniq("cy-tg");
    openChannelCreate("TELEGRAM_BOT");

    cy.findByLabelText(/display name/i).type(name);
    cy.findByLabelText(/bot token/i).type("0000000000:AAEtest_fake_bot_token_for_e2e_only");
    cy.findByRole("button", { name: /add channel/i }).click();

    // Step 2 — dev-mode dry-run webhook-registration confirmation. Gate on the
    // semantic confirmation controls (i18n-safe role/text), not a structural
    // testid: the step-2 wrapper testid isn't stable across dialogue-mfe builds,
    // but the "Done" CTA (and the webhook-registered success copy) are the
    // user-visible confirmation. The end-to-end proof is the channel landing in
    // the list below.
    cy.findByRole("button", { name: /^done$/i, timeout: 20_000 })
      .should("be.visible")
      .click();

    // Back on the channels list — the new channel is present.
    cy.location("pathname", { timeout: 20_000 }).should("match", /\/dialogue\/channels/);
    cy.findByText(name).should("be.visible");
  });

  // Create-surface coverage for the transport adapters whose ACTIVE flow needs
  // an external fake. Each: tile -> form renders with its representative field(s)
  // -> the Add Channel submit is present.
  const surfaces: ReadonlyArray<{
    type: string;
    fields: RegExp[];
  }> = [
    { type: "EMAIL", fields: [/display name/i] },
    { type: "TELEGRAM_CLIENT", fields: [/phone number/i] },
    { type: "SIGNAL", fields: [/device name/i, /phone number/i] },
    { type: "INSTAGRAM_DIRECT", fields: [/instagram user id/i, /facebook page id/i] },
    { type: "SOCIAL_X", fields: [/ayrshare profile key/i] },
  ];

  for (const { type, fields } of surfaces) {
    it(`renders the ${type} create form`, () => {
      openChannelCreate(type);
      cy.get(`[data-testid^="channel-create-"]`, { timeout: 20_000 }).should("exist");
      for (const label of fields) {
        cy.findByLabelText(label).scrollIntoView().should("be.visible");
      }
      // The submit lives at the bottom of a scrollable dialog — scroll it in.
      cy.findByRole("button", { name: /add channel/i })
        .scrollIntoView()
        .should("be.visible");
    });
  }

  // #2305: the Signal form's Trust-unknown-senders switch defaults to ON, so
  // flipping it off is the only way to reach the off-state that has no fill
  // to lean on. Guards against the border regressing to the ~1.4:1 plain
  // `cog-border` this ticket fixed, by asserting the emphasized token
  // (#64748B = rgb(100, 116, 139)) instead.
  it("Signal form's Trust-unknown-senders switch renders a high-contrast border when off (#2305)", () => {
    openChannelCreate("SIGNAL");
    cy.findByRole("switch", { name: /trust unknown senders/i })
      .scrollIntoView()
      .should("have.attr", "aria-checked", "true")
      .click()
      .should("have.attr", "aria-checked", "false")
      .should("have.css", "border-color", "rgb(100, 116, 139)");
  });
});


--- frontends/cypress/cypress/e2e/dialogue/contacts-groups.cy.ts (61 lines) ---
/**
 * Dialogue — contacts + contact-groups CRUD (UI).
 *
 * No single retired PW spec owned this journey (dialogue-broadcasts.spec.ts
 * seeded contacts/groups via the BFF); this is the fresh UI journey for the
 * Contacts surface. A contact requires a channel (the create form has a channel
 * <select>), so we seed one channel via the BFF first.
 *
 * Persona: P4 (org member) — contact/group create returns 201 for members.
 */
import { createTelegramChannel, uniq } from "./_helpers";

describe("dialogue: contacts and groups", () => {
  let channelName: string;

  beforeEach(() => {
    cy.login("P4");
    channelName = uniq("cy-cg-ch");
    createTelegramChannel(channelName);
    cy.visit("/dialogue/contacts");
    cy.findByRole("heading", { name: /^contacts$/i }).should("be.visible");
  });

  it("creates a contact group via the Manage Groups drawer", () => {
    const groupName = uniq("cy-group");

    cy.findByRole("button", { name: /manage groups/i }).click();
    cy.get('[data-testid="manage-groups-drawer"]').should("be.visible");
    cy.findByRole("button", { name: /new group/i }).click();

    cy.get('[data-testid="group-form-modal"]').should("be.visible").within(() => {
      cy.findByLabelText(/group name/i).type(groupName);
      cy.findByRole("button", { name: /^save$/i }).click();
    });

    cy.get('[data-testid="group-form-modal"]').should("not.exist");
    // The new group renders in TWO places at once: this drawer's row list AND
    // the group filter-chip row on the page behind it (ContactFilterBar re-fetches
    // groups on save). Scope to the drawer — the surface this test is actually
    // exercising — so the assertion doesn't collide with the filter chip.
    cy.get('[data-testid="manage-groups-drawer"]').within(() => {
      cy.findByText(groupName).should("exist");
    });
  });

  it("creates a contact against a channel", () => {
    const contactName = uniq("cy-person");

    cy.findByRole("button", { name: /add contact/i }).click();
    cy.get('[data-testid="contact-form-modal"]').should("be.visible").within(() => {
      cy.get('[data-testid="contact-channel-select"]').select(channelName);
      cy.findByLabelText(/identifier/i).type(`${Date.now() % 1_000_000}`);
      cy.findByLabelText(/display name/i).type(contactName);
      cy.findByRole("button", { name: /^save$/i }).click();
    });

    cy.get('[data-testid="contact-form-modal"]').should("not.exist");
    cy.findByText(contactName).should("exist");
  });
});


--- frontends/cypress/cypress/e2e/dialogue/conversations.cy.ts (84 lines) ---
/**
 * Dialogue — two-pane inbox + thread + composer.
 *
 * Subsumes the UI/create side of the retired dialogue specs: email-roundtrip
 * (conversation + composer + outbound status), edit-message and
 * notification-thread (the thread two-pane + message rendering). INBOUND
 * delivery (webhook/IMAP → worker → bubble) is NOT provable on this stack —
 * telegram-bot channels never reach a processable status with a fake token and
 * there is no mailpit/telegram-gateway — so the inbound-driven assertions of
 * edit-message / notification-thread are reported as an async-delivery gap
