/**
 * Dialogue — unauthenticated channel-webhook ingest surface.
 *
 * Subsumes the ingest side of the retired dialogue-telegram-webhook.spec.ts.
 * The webhook endpoint is the ONE dialogue surface with no JWT middleware: it
 * validates the signature and publishes to NATS, never touching Postgres. We
 * assert it ACCEPTS a well-formed Update (that is the contract this surface
 * owns). Whether that Update is later materialised into a conversation depends
 * on the channel reaching an ACTIVE/processable status, which a fake-token
 * telegram bot cannot do on this stack (no telegram gateway) — see the lane
 * report's inbound-delivery gap.
 *
 * Persona: P4 (org member) creates the channel; the webhook POST itself runs
 * with cookies cleared to prove the surface is genuinely unauthenticated.
 */
import {
  createTelegramChannel,
  postTelegramWebhook,
  telegramTextUpdate,
  DIALOGUE_API,
  dialogueBffUrl,
  uniq,
} from "./_helpers";

describe("dialogue: webhook ingest (unauthenticated surface)", () => {
  it("accepts a signed Telegram Update without a session cookie", () => {
    cy.login("P4");
    createTelegramChannel(uniq("cy-hook")).then((channel) => {
      // Drop the session — the webhook surface must accept unauthenticated.
      cy.clearCookies();
      const update = telegramTextUpdate({
        messageId: Date.now() % 900_000,
        chatId: 42_000_777,
        fromId: 99_000_777,
        text: uniq("hook-msg"),
      });
      postTelegramWebhook(channel.id, update).then((res) => {
        expect(res.status, "webhook accepts a signed Update").to.be.oneOf([200, 202, 204]);
      });
    });
  });

  it("does not sit behind JWT auth at the dialogue-bff plane (no 401)", () => {
    // Hitting the webhook path DIRECTLY on dialogue-bff (not the shell-bff
    // authenticated proxy) never yields 401 — it is outside the JWT middleware.
    // (A malformed body / unknown channel may 4xx, but never 401.)
    cy.request({
      method: "POST",
      url: `${dialogueBffUrl()}${DIALOGUE_API}/webhooks/telegram/00000000-0000-0000-0000-000000000000`,
      headers: { "Content-Type": "application/json" },
      body: "{}",
      failOnStatusCode: false,
    }).then((res) => {
      expect(res.status).to.not.eq(401);
    });
  });
});



